using System.Security.Claims;
using EmployeeMonitoringAPI.Data;
using EmployeeMonitoringAPI.Interfaces;
using EmployeeMonitoringAPI.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace EmployeeMonitoringAPI.Controllers;

[ApiController, Route("api/ManagerPortal/enterprise"), Authorize(Roles="Manager")]
public sealed class ManagerEnterpriseController(ApplicationDbContext db, IAuditService audit) : ControllerBase
{
 int ManagerId()=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 IQueryable<User> Team()=>db.Users.Where(x=>x.ManagerId==ManagerId()&&x.Role=="Employee"&&x.IsActive);
 Task<bool> Owns(int id)=>Team().AnyAsync(x=>x.UserId==id);
 IQueryable<Project> Projects()=>db.Projects.Where(x=>x.ManagerId==ManagerId()&&!x.IsArchived);

 [HttpGet("metadata")]
 public async Task<IActionResult> Metadata()
 {
  var keys=new[]{"TaskStatuses","TaskPriorities","ProjectStatuses","ProjectPriorities","AttendanceStatuses","LeaveStatuses","TimesheetStatuses","PerformanceRecommendations","OnboardingStages"};
  var values=await db.SystemSettings.Where(x=>keys.Contains(x.SettingKey)).ToDictionaryAsync(x=>x.SettingKey,x=>x.SettingValue.Split(',',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries));
  return Ok(values);
 }

 [HttpGet("team")]
 public async Task<IActionResult> TeamDashboard(string? search=null,int? departmentId=null,int? projectId=null,string? status=null,string sort="name",int page=1,int pageSize=10)
 {
  page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,5,100);var now=DateTime.UtcNow;var today=now.Date;var month=today.AddDays(-29);var q=Team().Include(x=>x.Department).AsQueryable();
  if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.FullName.Contains(search)||x.Email.Contains(search)||(x.EmployeeCode??"").Contains(search)||(x.PhoneNumber??"").Contains(search));
  if(departmentId.HasValue)q=q.Where(x=>x.DepartmentId==departmentId.Value);
  if(projectId.HasValue){if(!await Projects().AnyAsync(x=>x.ProjectId==projectId))return NotFound(new{message="Project not found"});q=q.Where(x=>db.ProjectAssignments.Any(a=>a.ProjectId==projectId&&a.UserId==x.UserId));}
  if(status=="Active")q=q.Where(x=>x.IsActive);if(status=="Inactive")q=q.Where(x=>!x.IsActive);q=sort switch{"attendance"=>q.OrderByDescending(x=>db.Attendances.Where(a=>a.UserId==x.UserId&&a.AttendanceDate>=month).Count(a=>a.AttendanceStatus=="Present")),"performance"=>q.OrderByDescending(x=>db.PerformanceReviews.Where(r=>r.EmployeeId==x.UserId).OrderByDescending(r=>r.ReviewDate).Select(r=>r.Rating).FirstOrDefault()),"tasks"=>q.OrderByDescending(x=>db.WorkTasks.Count(t=>t.AssignedToId==x.UserId&&t.Status!="Completed"&&t.Status!="Cancelled")),_=>q.OrderBy(x=>x.FullName)};
  var total=await q.CountAsync();var users=await q.Skip((page-1)*pageSize).Take(pageSize).ToListAsync();var ids=users.Select(x=>x.UserId).ToList();
  var attendance=await db.Attendances.Where(x=>ids.Contains(x.UserId)&&x.AttendanceDate>=month).ToListAsync();var tasks=await db.WorkTasks.Where(x=>ids.Contains(x.AssignedToId)).ToListAsync();var leaves=await db.Leaves.Where(x=>ids.Contains(x.UserId)&&x.Status=="Approved"&&x.FromDate<=today&&x.ToDate>=today).ToListAsync();var reviews=await db.PerformanceReviews.Where(x=>ids.Contains(x.EmployeeId)).OrderByDescending(x=>x.ReviewDate).ToListAsync();var assignments=await db.ProjectAssignments.Include(x=>x.Project).Where(x=>ids.Contains(x.UserId)&&!x.Project!.IsArchived).ToListAsync();
  var rows=users.Select(u=>{var ua=attendance.Where(x=>x.UserId==u.UserId).ToList();var ut=tasks.Where(x=>x.AssignedToId==u.UserId).ToList();var todayA=ua.FirstOrDefault(x=>x.AttendanceDate.Date==today);var workDays=Math.Max(1,Enumerable.Range(0,30).Select(i=>month.AddDays(i)).Count(d=>d.DayOfWeek is not(DayOfWeek.Saturday or DayOfWeek.Sunday)));var completed=ut.Count(x=>x.Status=="Completed");var latest=reviews.FirstOrDefault(x=>x.EmployeeId==u.UserId);return new{u.UserId,u.ProfileImage,u.EmployeeCode,u.FullName,department=u.Department?.Name,u.Designation,u.Email,u.PhoneNumber,currentProject=assignments.Where(x=>x.UserId==u.UserId&&x.Project!.Status!="Completed").OrderBy(x=>x.Project!.EndDate).Select(x=>new{x.ProjectId,x.Project!.ProjectName}).FirstOrDefault(),taskCompletion=ut.Count==0?0:Math.Round(completed*100d/ut.Count,1),attendancePercentage=Math.Round(ua.Count(x=>x.AttendanceStatus=="Present"||x.Status=="Present")*100d/workDays,1),todayStatus=leaves.Any(x=>x.UserId==u.UserId)?"On Leave":todayA?.AttendanceStatus??"Absent",currentLeaveStatus=leaves.Any(x=>x.UserId==u.UserId)?"Approved Leave":"None",workingHoursToday=todayA?.EffectiveHours??todayA?.TotalHours??0,activeTasks=ut.Count(x=>x.Status!="Completed"&&x.Status!="Cancelled"),pendingTasks=ut.Count(x=>x.Status is "Not Started" or "Assigned" or "Pending"),overdueTasks=ut.Count(x=>x.DueDate<now&&x.Status!="Completed"&&x.Status!="Cancelled"),performanceRating=latest?.Rating,lastLogin=u.LastLoginAt,accountStatus=u.IsActive?"Active":"Inactive"};}).ToList();
  var allIds=await Team().Select(x=>x.UserId).ToListAsync();var todayAll=await db.Attendances.Where(x=>allIds.Contains(x.UserId)&&x.AttendanceDate.Date==today).ToListAsync();var allTasks=await db.WorkTasks.Where(x=>allIds.Contains(x.AssignedToId)).ToListAsync();var allReviews=await db.PerformanceReviews.Where(x=>allIds.Contains(x.EmployeeId)).GroupBy(x=>x.EmployeeId).Select(g=>g.OrderByDescending(x=>x.ReviewDate).Select(x=>x.Rating).FirstOrDefault()).ToListAsync();var approvedToday=await db.Leaves.CountAsync(x=>allIds.Contains(x.UserId)&&x.Status=="Approved"&&x.FromDate<=today&&x.ToDate>=today);var summary=new{teamSize=allIds.Count,presentToday=todayAll.Count(x=>x.AttendanceStatus=="Present"||x.Status=="Present"),onLeave=approvedToday,lateEmployees=todayAll.Count(x=>x.LateMinutes>0),tasksDueToday=allTasks.Count(x=>x.DueDate.HasValue&&x.DueDate.Value.Date==today),overdueTasks=allTasks.Count(x=>x.DueDate<now&&x.Status!="Completed"&&x.Status!="Cancelled"),averageAttendance=allIds.Count==0?0:Math.Round(todayAll.Count*100d/allIds.Count,1),averagePerformance=allReviews.Count==0?0:Math.Round(allReviews.Average(x=>(double)x),2)};
  var departments=await Team().Where(x=>x.DepartmentId!=null).Select(x=>new{x.DepartmentId,name=x.Department!.Name}).Distinct().OrderBy(x=>x.name).ToListAsync();
  return Ok(new{items=rows,summary,filterOptions=new{departments},totalCount=total,page,pageSize,totalPages=(int)Math.Ceiling(total/(double)pageSize)});
 }

 [HttpGet("team/{id:int}")]
 public async Task<IActionResult> EmployeeProfile(int id)
 {
  var u=await Team().AsNoTracking().Include(x=>x.Department).FirstOrDefaultAsync(x=>x.UserId==id);
  if(u==null)return NotFound();
  var attendance=await db.Attendances.AsNoTracking().Where(x=>x.UserId==id).OrderByDescending(x=>x.AttendanceDate).Take(31).Select(x=>new{x.AttendanceId,x.AttendanceDate,x.CheckInTime,x.BreakStartTime,x.BreakEndTime,x.CheckOutTime,x.TotalHours,x.EffectiveHours,x.OvertimeHours,x.LateMinutes,x.AttendanceStatus,x.Status}).ToListAsync();
  var leaves=await db.Leaves.AsNoTracking().Where(x=>x.UserId==id).OrderByDescending(x=>x.AppliedAt).Take(25).Select(x=>new{x.LeaveId,x.LeaveType,x.FromDate,x.ToDate,x.IsHalfDay,x.Reason,x.Status,x.AppliedAt,x.ApprovalRemarks}).ToListAsync();
  var projects=await db.ProjectAssignments.AsNoTracking().Where(x=>x.UserId==id&&x.Project!=null).Select(x=>new{x.ProjectId,x.Project!.ProjectName,x.Project.ProjectCode,x.Project.Status,x.Project.ProgressPercentage,x.Project.EndDate}).ToListAsync();
  var tasks=await db.WorkTasks.AsNoTracking().Where(x=>x.AssignedToId==id).OrderByDescending(x=>x.CreatedAt).Take(50).Select(x=>new{x.TaskId,x.Title,x.Status,x.Priority,x.ProgressPercentage,x.DueDate,x.ProjectId,x.CreatedAt}).ToListAsync();
  var timesheets=await db.WeeklyTimesheets.AsNoTracking().Where(x=>x.EmployeeId==id).OrderByDescending(x=>x.WeekStartDate).Take(12).Select(x=>new{x.Id,x.WeekStartDate,x.WeekEndDate,x.TotalHours,x.Status,x.SubmittedAt,x.ManagerRemarks}).ToListAsync();
  var performance=await db.PerformanceReviews.AsNoTracking().Where(x=>x.EmployeeId==id).OrderByDescending(x=>x.ReviewDate).Select(x=>new{x.PerformanceReviewId,x.Year,x.Quarter,x.Rating,x.ManagerRemarks,x.PromotionRecommendation,x.IsReleased,x.ReviewDate}).ToListAsync();
  var training=await db.TrainingAssignments.AsNoTracking().Where(x=>x.UserId==id).Select(x=>new{x.TrainingAssignmentId,name=x.TrainingProgram!=null?x.TrainingProgram.Name:null,x.Status,x.Score,x.AssignedAt,x.CompletedAt}).ToListAsync();
  var documents=await db.DocumentFiles.AsNoTracking().Where(x=>x.UploadedById==id).OrderByDescending(x=>x.UploadedAt).Select(x=>new{x.DocumentId,x.OriginalFileName,x.Category,createdAt=x.UploadedAt}).ToListAsync();
  var emergency=await db.EmergencyContacts.AsNoTracking().Where(x=>x.UserId==id).Select(x=>new{x.EmergencyContactId,x.Name,x.Relationship,x.Phone,x.Email,x.IsPrimary}).ToListAsync();
  var activity=await db.ActivityLogs.AsNoTracking().Where(x=>x.UserId==id).OrderByDescending(x=>x.CreatedAt).Take(50).Select(x=>new{x.Id,x.Action,x.CreatedAt}).ToListAsync();
  return Ok(new{personal=new{u.UserId,u.ProfileImage,u.FullName,u.Email,u.PhoneNumber,u.DateOfBirth,u.Address},job=new{u.EmployeeCode,department=u.Department!=null?u.Department.Name:null,u.Designation,u.EmploymentType,u.EmploymentStatus,u.WorkLocation,u.DateOfJoining,u.LastLoginAt,u.IsActive},attendance,leaves,projects,tasks,timesheets,performance,training,documents,emergency,activity});
 }

 [HttpPost("team/{id:int}/message")]
 public async Task<IActionResult> Message(int id,MessageRequest r){if(!await Owns(id))return NotFound();if(string.IsNullOrWhiteSpace(r.Message))return BadRequest(new{message="Message is required"});var x=new EmployeeMessage{SenderId=ManagerId(),RecipientId=id,Subject=r.Subject.Trim(),Message=r.Message.Trim()};db.Add(x);db.Add(new Notification{UserId=id,Title=string.IsNullOrWhiteSpace(r.Subject)?"Message from Manager":r.Subject.Trim(),Message=r.Message.Trim(),Type="ManagerMessage",RelatedUrl="/employee/dashboard",DeduplicationKey=$"message:{Guid.NewGuid():N}"});await db.SaveChangesAsync();await audit.RecordAsync("EmployeeMessaged","EmployeeMessage",x.EmployeeMessageId.ToString(),actorUserId:ManagerId(),safeMetadata:new{RecipientId=id});return Ok(new{message="Message sent"});}

 [HttpGet("projects")]
 public async Task<IActionResult> ProjectDashboard(string? search=null,string? status=null,string? priority=null,string sort="deadline",int page=1,int pageSize=10){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,5,100);var q=Projects().Include(x=>x.Manager).AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.ProjectName.Contains(search)||x.ProjectCode.Contains(search)||x.Client.Contains(search));if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);if(!string.IsNullOrWhiteSpace(priority))q=q.Where(x=>x.Priority==priority);q=sort=="name"?q.OrderBy(x=>x.ProjectName):sort=="progress"?q.OrderByDescending(x=>x.ProgressPercentage):q.OrderBy(x=>x.EndDate);var total=await q.CountAsync();var items=await q.Skip((page-1)*pageSize).Take(pageSize).Select(x=>new{x.ProjectId,x.ProjectCode,x.ProjectName,x.Description,x.Client,x.Priority,x.Status,x.StartDate,deadline=x.EndDate,progress=db.WorkTasks.Any(t=>t.ProjectId==x.ProjectId)?(int)Math.Round(db.WorkTasks.Where(t=>t.ProjectId==x.ProjectId).Average(t=>t.ProgressPercentage)):x.ProgressPercentage,x.Budget,teamMembers=db.ProjectAssignments.Count(a=>a.ProjectId==x.ProjectId),manager=x.Manager!.FullName,totalTasks=db.WorkTasks.Count(t=>t.ProjectId==x.ProjectId),completedTasks=db.WorkTasks.Count(t=>t.ProjectId==x.ProjectId&&t.Status=="Completed"),pendingTasks=db.WorkTasks.Count(t=>t.ProjectId==x.ProjectId&&t.Status!="Completed"&&t.Status!="Cancelled"),overdueTasks=db.WorkTasks.Count(t=>t.ProjectId==x.ProjectId&&t.DueDate<DateTime.UtcNow&&t.Status!="Completed"&&t.Status!="Cancelled")}).ToListAsync();return Ok(Page(items,total,page,pageSize));}

 [HttpGet("projects/{id:int}")]
 public async Task<IActionResult> ProjectDetails(int id){var p=await Projects().Include(x=>x.Department).Include(x=>x.Manager).FirstOrDefaultAsync(x=>x.ProjectId==id);if(p==null)return NotFound();return Ok(new{overview=p,members=await db.ProjectAssignments.Include(x=>x.User).Where(x=>x.ProjectId==id).Select(x=>new{x.UserId,x.User!.FullName,x.User.EmployeeCode,x.User.Designation,x.AssignedAt}).ToListAsync(),tasks=await db.WorkTasks.Include(x=>x.AssignedTo).Where(x=>x.ProjectId==id).OrderBy(x=>x.DueDate).Select(x=>new{x.TaskId,x.Title,x.Description,x.Priority,x.Status,x.ProgressPercentage,x.EstimatedHours,x.DueDate,x.AssignedToId,employee=x.AssignedTo!.FullName}).ToListAsync(),timeline=await db.ProjectHistories.Where(x=>x.ProjectId==id).OrderByDescending(x=>x.UpdatedAt).ToListAsync(),files=await db.DocumentFiles.Where(x=>x.ProjectId==id).OrderByDescending(x=>x.UploadedAt).ToListAsync(),activity=await db.AuditLogs.Where(x=>x.EntityType=="Project"&&x.EntityId==id.ToString()).OrderByDescending(x=>x.Timestamp).Take(50).ToListAsync(),discussion=await db.ProjectDiscussions.Include(x=>x.Author).Where(x=>x.ProjectId==id).OrderBy(x=>x.CreatedAt).Select(x=>new{x.ProjectDiscussionId,x.Message,x.CreatedAt,author=x.Author!.FullName}).ToListAsync()});}

 [HttpPost("projects/{id:int}/discussion")]
 public async Task<IActionResult> Discuss(int id,MessageRequest r){if(!await Projects().AnyAsync(x=>x.ProjectId==id))return NotFound();if(string.IsNullOrWhiteSpace(r.Message))return BadRequest(new{message="Message is required"});var x=new ProjectDiscussion{ProjectId=id,AuthorId=ManagerId(),Message=r.Message.Trim()};db.Add(x);await db.SaveChangesAsync();await audit.RecordAsync("ProjectDiscussionAdded","Project",id.ToString(),actorUserId:ManagerId());return Ok(new{message="Discussion posted"});}

 [HttpDelete("tasks/{id:int}")]
 public async Task<IActionResult> DeleteTask(int id){var x=await db.WorkTasks.Include(t=>t.AssignedTo).FirstOrDefaultAsync(t=>t.TaskId==id&&t.AssignedTo!.ManagerId==ManagerId());if(x==null)return NotFound();if(x.Status is "Completed" or "Under Review" or "Ready for Review")return Conflict(new{message="Completed or review-stage tasks cannot be deleted"});var projectId=x.ProjectId;db.Remove(x);await db.SaveChangesAsync();if(projectId.HasValue)await Recalculate(projectId.Value);await audit.RecordAsync("TaskDeleted","WorkTask",id.ToString(),actorUserId:ManagerId(),safeMetadata:new{x.Title,x.AssignedToId});return Ok(new{message="Task deleted"});}

 [HttpPatch("tasks/{id:int}/status")]
 public async Task<IActionResult> TaskStatus(int id,TaskStatusEnterpriseRequest r){var x=await db.WorkTasks.Include(t=>t.AssignedTo).FirstOrDefaultAsync(t=>t.TaskId==id&&t.AssignedTo!.ManagerId==ManagerId());if(x==null)return NotFound();var status=r.Status?.Trim();if(status is not ("Completed" or "Reopened" or "Cancelled"))return BadRequest(new{message="Manager status must be Completed, Reopened or Cancelled"});if(status=="Completed"&&x.Status!="Ready for Review")return Conflict(new{message="Only tasks submitted for review can be approved"});if(status=="Reopened"&&x.Status is not ("Ready for Review" or "Completed"))return Conflict(new{message="Only reviewed tasks can be reopened"});if(status=="Reopened"&&string.IsNullOrWhiteSpace(r.Feedback))return BadRequest(new{message="Rejection remarks are required"});x.Status=status;x.ProgressPercentage=status=="Completed"?100:Math.Clamp(r.ProgressPercentage,0,99);x.ManagerFeedback=r.Feedback?.Trim();x.CompletedAt=status=="Completed"?DateTime.UtcNow:null;if(status=="Reopened")x.SubmittedAt=null;db.Add(new Notification{UserId=x.AssignedToId,Title=$"Task {status.ToLowerInvariant()}",Message=$"{x.Title} was {status.ToLowerInvariant()} by your Manager. {x.ManagerFeedback}".Trim(),Type="TaskReview",RelatedUrl="/employee/projects",DeduplicationKey=$"task:{id}:review:{status}:{DateTime.UtcNow.Ticks}"});await db.SaveChangesAsync();if(x.ProjectId.HasValue)await Recalculate(x.ProjectId.Value);await audit.RecordAsync("TaskStatusChanged","WorkTask",id.ToString(),actorUserId:ManagerId(),safeMetadata:new{Status=status,x.ProgressPercentage});return Ok(new{message="Task status updated"});}

 [HttpGet("attendance")]
 public async Task<IActionResult> AttendanceDashboard(DateTime? from=null,DateTime? to=null,int? employeeId=null,string? status=null,string sort="date",int page=1,int pageSize=10){if(from.HasValue&&to.HasValue&&from.Value.Date>to.Value.Date)return BadRequest(new{message="From date cannot be after to date"});var ids=await Team().Select(x=>x.UserId).ToListAsync();if(employeeId.HasValue&&!ids.Contains(employeeId.Value))return NotFound();var selected=employeeId.HasValue?new[]{employeeId.Value}:ids.ToArray();var start=(from??DateTime.UtcNow.Date).Date;var end=(to??start).Date.AddDays(1);var q=db.Attendances.Include(x=>x.User).Where(x=>selected.Contains(x.UserId)&&x.AttendanceDate>=start&&x.AttendanceDate<end);if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.AttendanceStatus==status||x.Status==status);q=sort=="employee"?q.OrderBy(x=>x.User!.FullName):sort=="hours"?q.OrderByDescending(x=>x.EffectiveHours):q.OrderByDescending(x=>x.AttendanceDate);var total=await q.CountAsync();var rows=await q.Skip((Math.Max(1,page)-1)*Math.Clamp(pageSize,5,100)).Take(Math.Clamp(pageSize,5,100)).Select(x=>new{x.AttendanceId,x.UserId,employee=x.User!.FullName,x.AttendanceDate,x.CheckInTime,x.BreakStartTime,x.BreakEndTime,x.CheckOutTime,totalHours=x.EffectiveHours>0?x.EffectiveHours:x.TotalHours,x.OvertimeHours,x.LateMinutes,status=x.AttendanceStatus,missingCheckout=x.CheckInTime!=null&&x.CheckOutTime==null}).ToListAsync();var all=await db.Attendances.Where(x=>selected.Contains(x.UserId)&&x.AttendanceDate>=start&&x.AttendanceDate<end).ToListAsync();var summary=new{present=all.Count(x=>x.AttendanceStatus=="Present"),absent=Math.Max(0,selected.Length*Math.Max(1,(end-start).Days)-all.Count),late=all.Count(x=>x.LateMinutes>0),wfh=all.Count(x=>x.AttendanceStatus=="WFH"),halfDay=all.Count(x=>x.AttendanceStatus=="Half Day"),missingCheckout=all.Count(x=>x.CheckInTime!=null&&x.CheckOutTime==null),averageWorkingHours=all.Count==0?0:Math.Round(all.Average(x=>x.EffectiveHours>0?x.EffectiveHours:x.TotalHours),2)};var trends=all.GroupBy(x=>x.AttendanceDate.Date).OrderBy(x=>x.Key).Select(g=>new{date=g.Key,present=g.Count(x=>x.AttendanceStatus=="Present"),late=g.Count(x=>x.LateMinutes>0),hours=Math.Round(g.Average(x=>x.EffectiveHours>0?x.EffectiveHours:x.TotalHours),2)});var corrections=await db.AttendanceRegularizations.Include(x=>x.User).Where(x=>selected.Contains(x.UserId)&&x.Status=="Pending").OrderBy(x=>x.RequestedAt).Select(x=>new{x.RequestId,x.UserId,employee=x.User!.FullName,x.RequestedCheckIn,x.RequestedCheckOut,x.Reason,x.Status,x.RequestedAt}).ToListAsync();return Ok(new{items=rows,summary,trends,corrections,totalCount=total,page=Math.Max(1,page),pageSize=Math.Clamp(pageSize,5,100),totalPages=(int)Math.Ceiling(total/(double)Math.Clamp(pageSize,5,100))});}

 [HttpPatch("attendance/corrections/{id:int}")]
 public async Task<IActionResult> AttendanceCorrection(int id,DecisionRequest r){var x=await db.AttendanceRegularizations.Include(x=>x.User).Include(x=>x.Attendance).FirstOrDefaultAsync(x=>x.RequestId==id);if(x==null)return NotFound();if(x.User!.ManagerId!=ManagerId())return Forbid();if(x.Status!="Pending")return Conflict(new{message="Correction already reviewed"});if(r.Decision is not("Approved" or "Rejected"))return BadRequest(new{message="Decision must be Approved or Rejected"});if(r.Decision=="Rejected"&&string.IsNullOrWhiteSpace(r.Comments))return BadRequest(new{message="Rejection remarks are required"});x.Status=r.Decision;x.ApprovedById=ManagerId();x.ApprovedAt=DateTime.UtcNow;x.ManagerRemarks=r.Comments;if(r.Decision=="Approved"){if(x.Attendance==null)return Conflict(new{message="The attendance record linked to this correction no longer exists"});if(x.RequestedCheckOut<=x.RequestedCheckIn||x.RequestedCheckIn.Date!=x.Attendance.AttendanceDate.Date||x.RequestedCheckOut.Date!=x.Attendance.AttendanceDate.Date)return BadRequest(new{message="Correction times must form a valid range on the attendance date"});x.Attendance.CheckInTime=x.RequestedCheckIn;x.Attendance.CheckOutTime=x.RequestedCheckOut;x.Attendance.TotalHours=Math.Round((x.RequestedCheckOut-x.RequestedCheckIn).TotalHours,2);x.Attendance.EffectiveHours=Math.Round(Math.Max(0,x.Attendance.TotalHours-x.Attendance.BreakMinutes/60d),2);x.Attendance.OvertimeHours=Math.Round(Math.Max(0,x.Attendance.EffectiveHours-9),2);x.Attendance.LateMinutes=x.RequestedCheckIn.TimeOfDay>new TimeSpan(9,40,0)?(int)(x.RequestedCheckIn.TimeOfDay-new TimeSpan(9,40,0)).TotalMinutes:0;x.Attendance.AttendanceStatus=x.Attendance.EffectiveHours>=9?(x.Attendance.LateMinutes>0?"Late":"Present"):x.Attendance.EffectiveHours>=4?"Half Day":"Absent";x.Attendance.Status=x.Attendance.AttendanceStatus;}db.Add(new Notification{UserId=x.UserId,Title="Attendance correction "+r.Decision.ToLowerInvariant(),Message=r.Comments??$"Your correction was {r.Decision.ToLowerInvariant()}.",Type="AttendanceCorrection",RelatedUrl="/employee/attendance",DeduplicationKey=$"attendance-correction:{id}:{r.Decision}"});await db.SaveChangesAsync();await audit.RecordAsync("AttendanceCorrection"+r.Decision,"AttendanceRegularization",id.ToString(),actorUserId:ManagerId());return Ok(new{message="Attendance correction reviewed"});}

 [HttpGet("leaves")]
 public async Task<IActionResult> LeaveDashboard(string? search=null,string? status=null,string? leaveType=null,DateTime? from=null,DateTime? to=null,string sort="newest",int page=1,int pageSize=10){var ids=await Team().Select(x=>x.UserId).ToListAsync();var q=db.Leaves.Include(x=>x.User).Where(x=>ids.Contains(x.UserId));if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.User!.FullName.Contains(search));if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);if(!string.IsNullOrWhiteSpace(leaveType))q=q.Where(x=>x.LeaveType==leaveType);if(from.HasValue)q=q.Where(x=>x.ToDate>=from.Value.Date);if(to.HasValue)q=q.Where(x=>x.FromDate<=to.Value.Date);q=sort=="oldest"?q.OrderBy(x=>x.AppliedAt):sort=="employee"?q.OrderBy(x=>x.User!.FullName):q.OrderByDescending(x=>x.AppliedAt);var total=await q.CountAsync();var rows=await q.Skip((Math.Max(1,page)-1)*Math.Clamp(pageSize,5,100)).Take(Math.Clamp(pageSize,5,100)).Select(x=>new{x.LeaveId,x.UserId,employee=x.User!.FullName,x.LeaveType,x.AppliedAt,x.FromDate,x.ToDate,days=x.IsHalfDay?.5:EF.Functions.DateDiffDay(x.FromDate,x.ToDate)+1,x.Reason,x.AttachmentUrl,balance=db.LeaveBalances.Where(b=>b.UserId==x.UserId).Select(b=>b.TotalLeaves-b.UsedLeaves).FirstOrDefault(),x.Status,x.ClarificationRequest,x.ApprovalRemarks,x.CancellationRequestedAt,x.CancellationReason,holidayCollision=db.CompanyHolidays.Any(h=>h.IsActive&&h.HolidayDate>=x.FromDate&&h.HolidayDate<=x.ToDate),conflictingApprovedLeave=db.Leaves.Any(l=>l.LeaveId!=x.LeaveId&&l.UserId==x.UserId&&l.Status=="Approved"&&l.FromDate<=x.ToDate&&l.ToDate>=x.FromDate)}).ToListAsync();var calendar=await db.Leaves.Include(x=>x.User).Where(x=>ids.Contains(x.UserId)&&x.Status=="Approved"&&(from==null||x.ToDate>=from)&&(to==null||x.FromDate<=to)).Select(x=>new{x.UserId,employee=x.User!.FullName,x.FromDate,x.ToDate,x.LeaveType}).ToListAsync();return Ok(new{items=rows,calendar,totalCount=total,page=Math.Max(1,page),pageSize=Math.Clamp(pageSize,5,100),totalPages=(int)Math.Ceiling(total/(double)Math.Clamp(pageSize,5,100))});}

 [HttpPatch("leaves/{id:int}/clarification")]
 public async Task<IActionResult> Clarification(int id,MessageRequest r){var x=await db.Leaves.Include(x=>x.User).FirstOrDefaultAsync(x=>x.LeaveId==id);if(x==null)return NotFound();if(x.User!.ManagerId!=ManagerId())return Forbid();if(x.Status!="Pending")return Conflict(new{message="Only pending leave requests can request clarification"});if(string.IsNullOrWhiteSpace(r.Message))return BadRequest(new{message="Clarification question is required"});x.Status="Clarification Requested";x.ClarificationRequest=r.Message.Trim();db.Add(new Notification{UserId=x.UserId,Title="Leave clarification requested",Message=r.Message.Trim(),Type="LeaveClarification",RelatedUrl="/employee/attendance",DeduplicationKey=$"leave:{id}:clarification"});await db.SaveChangesAsync();await audit.RecordAsync("LeaveClarificationRequested","Leave",id.ToString(),actorUserId:ManagerId());return Ok(new{message="Clarification requested"});}

 [HttpGet("timesheets")]
 public async Task<IActionResult> TimesheetDashboard(string? search=null,string? status=null,DateTime? from=null,DateTime? to=null,string sort="newest",int page=1,int pageSize=10){var q=db.WeeklyTimesheets.Include(x=>x.Employee).Include(x=>x.Lines).ThenInclude(x=>x.Project).Include(x=>x.Lines).ThenInclude(x=>x.Task).Where(x=>x.ManagerId==ManagerId());if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Employee!.FullName.Contains(search));if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);if(from.HasValue)q=q.Where(x=>x.WeekEndDate>=from);if(to.HasValue)q=q.Where(x=>x.WeekStartDate<=to);q=sort=="oldest"?q.OrderBy(x=>x.WeekStartDate):sort=="hours"?q.OrderByDescending(x=>x.TotalHours):q.OrderByDescending(x=>x.WeekStartDate);var total=await q.CountAsync();var list=await q.Skip((Math.Max(1,page)-1)*Math.Clamp(pageSize,5,100)).Take(Math.Clamp(pageSize,5,100)).ToListAsync();var items=list.Select(x=>new{x.Id,x.EmployeeId,employee=x.Employee!.FullName,x.WeekStartDate,x.WeekEndDate,x.TotalHours,billableHours=x.Lines.Where(l=>l.BillingType=="Billable").Sum(l=>l.TotalHours),nonBillableHours=x.Lines.Where(l=>l.BillingType!="Billable").Sum(l=>l.TotalHours),utilization=x.TotalHours==0?0:Math.Round(x.Lines.Where(l=>l.BillingType=="Billable").Sum(l=>l.TotalHours)*100/x.TotalHours,1),x.Status,x.SubmittedAt,x.ManagerRemarks,lines=x.Lines.Select(l=>new{date=x.WeekStartDate,l.ProjectId,project=l.Project!.ProjectName,l.TaskId,task=l.TaskId.HasValue?l.Task!.Title:null,hours=l.TotalHours,description=l.WorkDescription,billable=l.BillingType=="Billable"})});var all=await db.WeeklyTimesheets.Include(x=>x.Lines).Where(x=>x.ManagerId==ManagerId()&&(from==null||x.WeekEndDate>=from)&&(to==null||x.WeekStartDate<=to)).ToListAsync();var summary=new{weeklyHours=all.Sum(x=>x.TotalHours),approvedHours=all.Where(x=>x.Status=="Approved").Sum(x=>x.TotalHours),pending=all.Count(x=>x.Status=="Submitted"),averageUtilization=all.Count==0?0:Math.Round(all.Average(x=>x.TotalHours==0?0:(double)(x.Lines.Where(l=>l.BillingType=="Billable").Sum(l=>l.TotalHours)*100/x.TotalHours)),1)};return Ok(new{items,summary,totalCount=total,page=Math.Max(1,page),pageSize=Math.Clamp(pageSize,5,100),totalPages=(int)Math.Ceiling(total/(double)Math.Clamp(pageSize,5,100))});}

 [HttpGet("performance")]
 public async Task<IActionResult> PerformanceDashboard(int? year=null,string quarter="Q1",string? search=null,string sort="rating",int page=1,int pageSize=10){var y=year??DateTime.UtcNow.Year;var q=Team();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.FullName.Contains(search)||(x.EmployeeCode??"").Contains(search));var total=await q.CountAsync();var users=await q.OrderBy(x=>x.FullName).Skip((Math.Max(1,page)-1)*Math.Clamp(pageSize,5,100)).Take(Math.Clamp(pageSize,5,100)).ToListAsync();var ids=users.Select(x=>x.UserId).ToList();var reviews=await db.PerformanceReviews.Where(x=>ids.Contains(x.EmployeeId)&&x.Year==y&&x.Quarter==quarter).ToListAsync();var tasks=await db.WorkTasks.Where(x=>ids.Contains(x.AssignedToId)).ToListAsync();var attendance=await db.Attendances.Where(x=>ids.Contains(x.UserId)&&x.AttendanceDate.Year==y).ToListAsync();var training=await db.TrainingAssignments.Where(x=>ids.Contains(x.UserId)).ToListAsync();var items=users.Select(u=>{var r=reviews.FirstOrDefault(x=>x.EmployeeId==u.UserId);var t=tasks.Where(x=>x.AssignedToId==u.UserId).ToList();var a=attendance.Where(x=>x.UserId==u.UserId).ToList();return new{u.UserId,u.FullName,u.EmployeeCode,goals=r?.Goals,kpis=r?.Kpis,attendance=a.Count==0?0:Math.Round(a.Count(x=>x.AttendanceStatus=="Present")*100d/a.Count,1),taskCompletion=t.Count==0?0:Math.Round(t.Count(x=>x.Status=="Completed")*100d/t.Count,1),quality=r?.WorkQuality,punctuality=r?.Timeliness,training=training.Count(x=>x.UserId==u.UserId&&x.Status=="Completed"),behavior=r?.BehaviorScore,managerReview=r?.ManagerRemarks,overallRating=r?.Rating,reviewHistory=reviews.Where(x=>x.EmployeeId==u.UserId).OrderByDescending(x=>x.ReviewDate),promotionRecommendation=r?.PromotionRecommendation,status=r==null?"Not Submitted":r.IsReleased?"Released":"Draft"};}).ToList();if(sort=="name")items=items.OrderBy(x=>x.FullName).ToList();else items=items.OrderByDescending(x=>x.overallRating??0).ToList();return Ok(new{items,summary=new{reviewed=reviews.Count,averageRating=reviews.Count==0?0:Math.Round(reviews.Average(x=>x.Rating),2),recommended=reviews.Count(x=>x.PromotionRecommendation=="Recommended")},totalCount=total,page=Math.Max(1,page),pageSize=Math.Clamp(pageSize,5,100),totalPages=(int)Math.Ceiling(total/(double)Math.Clamp(pageSize,5,100))});}

 async Task<string[]>Setting(string key)=>((await db.SystemSettings.Where(x=>x.SettingKey==key).Select(x=>x.SettingValue).FirstOrDefaultAsync())??"").Split(',',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries);
 async Task Recalculate(int id){var tasks=await db.WorkTasks.Where(x=>x.ProjectId==id).ToListAsync();var p=await db.Projects.FindAsync(id);if(p==null)return;p.ProgressPercentage=tasks.Count==0?0:(int)Math.Round(tasks.Average(x=>x.ProgressPercentage));if(p.ProgressPercentage==100)p.Status="Completed";p.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();}
 static object Page<T>(List<T>items,int total,int page,int size)=>new{items,totalCount=total,page,pageSize=size,totalPages=(int)Math.Ceiling(total/(double)size)};
}
